// 自己造成伤害（点数未满 99 才计）
HostBehavior::MbQianlong => match event {
    // 开局面：游戏首个阶段帧（原生准备阶段开始在建局时隐式提交，
    // 首个阶段帧为摸牌阶段开始——登记差异：时点后移一个阶段）
    EventData::Phase { begin: true, .. } => ctx.state.turn.phase_number == 1,
    EventData::CardsDrawn { player, .. } => {
